input[type="range"] {
  appearance: none; width: 100%; min-width: 0; max-width: 100%; height: 32px;
  flex: 1 1 auto; margin: 0; padding: 0; border: 0; border-radius: 4px;
  background: transparent; cursor: pointer; accent-color: var(--lt-accent-text);
}
input[type="range"]::-webkit-slider-runnable-track { height: 4px; background: var(--lt-border-strong); border-radius: 99px; }
input[type="range"]::-webkit-slider-thumb { appearance: none; width: 16px; height: 16px; margin-top: -6px; border: 2px solid var(--lt-bg); border-radius: 50%; background: var(--lt-fg); }
input[type="range"]::-moz-range-track { height: 4px; background: var(--lt-border-strong); border-radius: 99px; }
input[type="range"]::-moz-range-thumb { width: 12px; height: 12px; border: 2px solid var(--lt-bg); border-radius: 50%; background: var(--lt-fg); }
.lt-field > input[type="range"] { flex: none; }
.lt-badge.accent { background: var(--lt-accent-soft); color: var(--lt-fg); }
.lt-badge.ok { background: var(--lt-success-soft); color: var(--lt-fg); }
.lt-badge.warn { background: var(--lt-warning-soft); color: var(--lt-fg); }
.lt-badge.bad { background: var(--lt-danger-soft); color: var(--lt-fg); }
.lt-choice[aria-pressed="true"] b, .lt-choice.selected b { color: var(--lt-fg); }

